// Junta cada fragmento con su vector.
// El nodo HTTP devuelve los embeddings en el mismo orden en que recibió los
// items, así que se emparejan por posición.

const fragmentos = $('Base de conocimiento').all().map((i) => i.json);
const vectores = $input.all().map((i) => i.json.embedding.values);

if (fragmentos.length !== vectores.length) {
  throw new Error(
    `Se indexaron ${vectores.length} vectores para ${fragmentos.length} fragmentos`
  );
}

const indice = fragmentos.map((f, i) => ({ ...f, vector: vectores[i] }));

// Un solo item con el índice entero adentro: así los nodos de abajo lo leen
// con $('Armar el indice').first() sin recorrer nada.
return [{ json: { indice, fragmentos: indice.length, dimensiones: vectores[0].length } }];

