// Búsqueda semántica, escrita a mano para que se vea qué hace.
//
// UMBRAL: hay que calibrarlo mirando los puntajes de la primera corrida.
// Con text-embedding-004 y textos en español, lo relevante suele caer entre
// 0.60 y 0.80, y lo que no tiene nada que ver entre 0.30 y 0.50.
const UMBRAL = 0.62;
const CUANTOS = 3;

function coseno(a, b) {
  let punto = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i++) {
    punto += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return punto / (Math.sqrt(na) * Math.sqrt(nb));
}

const indice = $('Armar el indice').first().json.indice;
const correos = $('Correos entrantes').all().map((i) => i.json);
const vectores = $input.all().map((i) => i.json.embedding.values);

const salida = [];

for (let i = 0; i < correos.length; i++) {
  const correo = correos[i];
  const v = vectores[i];

  const puntuados = indice
    .map((f) => ({
      id: f.id,
      titulo: f.titulo,
      texto: f.texto,
      vigente_desde: f.vigente_desde,
      similitud: Number(coseno(v, f.vector).toFixed(4)),
    }))
    .sort((a, b) => b.similitud - a.similitud);

  const top = puntuados.slice(0, CUANTOS);
  const mejor = top[0]?.similitud ?? 0;

  salida.push({
    json: {
      ...correo,
      recuperados: top,
      ids_recuperados: top.map((f) => f.id),
      mejor_similitud: mejor,
      hay_respaldo: mejor >= UMBRAL,
      // Para la diapositiva de calibración: todos los puntajes, no solo el top.
      _todos: puntuados.map((f) => ({ id: f.id, s: f.similitud })),
    },
  });
}

return salida;

